import"./chunk-2NFLSA4Y.js";var s={pressure:{theory:{concept:"[[Pressure is the physical quantity equal to the force acting perpendicular to a surface divided by the area of that surface: p = F / A.]] Its unit is the pascal, 1 Pa = 1 N/m\xB2 \u2014 a very small pressure, so kilopascals are often used (1 kPa = 1000 Pa)."},section:{area:{title:"Small area, big pressure",text:"A 60 kg person weighs about 590 N. Standing in boots (about 300 cm\xB2 for both soles) they press on the snow with about 20 kPa and sink in. On skis (about 3000 cm\xB2) the pressure is ten times smaller, 2 kPa, and they glide on top. On a 10 cm\xB2 high heel it is about 590 kPa \u2014 enough to sink straight to the ground. The weight is the same each time; only the area changes."},everyday:{title:"Using pressure",text:"We make the area small when we want a big pressure: knives, needles and nails are sharp, so a small force cuts or pierces. We make the area large when we want a small pressure: tractors and tanks have wide tracks, buildings stand on wide foundations, and backpacks have wide straps so they do not hurt the shoulders."},liquid:{title:"Pressure in a liquid",text:"A liquid presses on everything in it because of the weight of the liquid above. A column of height h and density \u03C1 presses with p = \u03C1\xB7g\xB7h. [[The pressure depends only on the depth, not on the shape of the container or on how much liquid there is in total.]] At a given depth it presses equally in every direction \u2014 sideways and upwards as well as downwards \u2014 which is why the probe feels the same push from all sides."},depth:{title:"Deeper means more pressure",text:"Every 10 m of water adds about 100 kPa \u2014 as much as the whole atmosphere above us. A diver at 10 m feels twice the pressure of the surface, at 20 m three times. That is why dams are thicker at the bottom, and why submarines and deep-sea probes need very strong hulls: at the bottom of the Mariana Trench, 11 km down, the pressure is over 1000 atmospheres."},atmosphere:{title:"The air presses too",text:"We live at the bottom of an ocean of air. At sea level the air presses with p\u2080 \u2248 101 kPa, about 10 tonnes on every square metre. We do not feel it because the pressure inside our bodies is the same. In 1643 Evangelista Torricelli showed that this pressure holds up a column of about 76 cm of mercury \u2014 the first barometer. The total pressure under water is p\u2080 + \u03C1\xB7g\xB7h."},check:{title:"Check your understanding",text:"A 60 kg person stands on 300 cm\xB2. What is the pressure? (About 20 kPa.) On skis the area is ten times larger. (About 2 kPa.) How deep must you dive in water for the pressure to double? (About 10 m.) Does a tall, thin tank of water press harder on its bottom than a wide one of the same depth? (No \u2014 only the depth matters.) Test each answer in the simulation."}},formula:{pressure:"Pressure: force per unit area",pascal:"The pascal: one newton on one square metre",liquid:"Pressure of a liquid at depth h",total:"Total pressure under the surface (p\u2080: the air above)",atmosphere:"Air pressure at sea level"},variable:{pressure:"Pressure",force:"Force perpendicular to the surface",area:"Area",density:"Density of the liquid",gravity:"Gravitational field strength",depth:"Depth below the surface"},assumption:{even:"The force is spread evenly over the whole contact area.",snow:"Snow is treated like a soft spring bed: the depth is proportional to the pressure (real snow packs down unevenly). It is 80 cm deep, with hard ground below.",liquid:"The liquid is at rest and equally dense everywhere; the probe is so small that it does not disturb the liquid.",scale:"The person and the probe are drawn schematically. The footwear is drawn as wide as its area would be with a sole 25 cm long."},param:{experiment:"Experiment",area:"Area under the feet",mass:"Mass of the person",liquid:"Liquid",tankDepth:"Depth of the tank",gravity:"Gravity",timeStep:"Time step"},hint:{area:"The total area of the soles that touch the snow.",tankDepth:"The probe goes down to the bottom of the tank."},option:{snow:"Standing on snow",liquid:"Diving into a liquid"},preset:{heels:"High heels",boots:"Boots",snowshoes:"Snowshoes",skis:"Skis"},liquid:{water:"Fresh water",seaWater:"Sea water",oil:"Oil",mercury:"Mercury"},measure:{pressure:"Pressure on the snow",force:"Weight (force on the snow)",sinking:"How deep the feet sink",liquidPressure:"Pressure of the liquid",depth:"Depth of the probe",totalPressure:"Total pressure (with the air)",bottomPressure:"Pressure of the liquid at the bottom",density:"Density of the liquid",oneAtmosphere:"Depth that adds one atmosphere"},view:{sole:"{area} \xB7 p = {pressure}",sinks:"sinks {depth}",toGround:"sinks to the ground",probe:"h = {depth} \xB7 \u03C1gh = {liquid} \xB7 total {total}",air:"Air: p\u2080 = {pressure}"},graph:{depthPressure:"Pressure of the liquid against depth",sinking:"Sinking depth against pressure"},challenge:{stayOnTop:{title:"Stay on top",description:"Let a person of at least 60 kg stand on the snow without sinking more than 2 cm.",hint:"Spread the weight: the pressure must be at most about 2.4 kPa."},highHeel:{title:"500 kilopascals",description:"Make the person press on the snow with a pressure of at least 500 kPa.",hint:"Make the area very small, like a high heel."},oneAtmosphere:{title:"One more atmosphere",description:"Fill the tank with fresh water so deep that the water at the bottom presses as much as the whole atmosphere (101.3 kPa).",hint:"h = p / (\u03C1\xB7g) \u2248 10.3 m."},samePressure:{title:"Heavier, same pressure",description:"On the Earth, let a person of at least 90 kg press on the snow exactly as hard as a 60 kg person in boots (19.6 kPa).",hint:"1.5 times the weight needs 1.5 times the area."},mercury:{title:"Heavy liquid",description:"Make the liquid at the bottom press with at least 1000 kPa, using mercury.",hint:"Mercury is 13.5 times denser than water: you need about 7.5 m."},moonBoots:{title:"Boots on the Moon",description:"On the Moon, let a person of at least 60 kg stand in boots (300 cm\xB2 or less) and sink no more than 3 cm.",hint:"On the Moon the weight is six times smaller, and so is the pressure."}}}},a={sim:s};export{a as default,s as sim};
